// Prüfe ob Meldung vollständig ist
const meldung = $input.first().json[0];
if (!meldung) throw new Error('Meldung nicht gefunden');
if (meldung.status !== 'bereit') throw new Error('Status muss bereit sein');
if (!meldung.ama_meldepositionen || meldung.ama_meldepositionen.length === 0) throw new Error('Keine Meldepositionen');
return [{ json: meldung }];

// AMA XML-Format (vereinfacht, echtes Format nach AMA-Spezifikation anpassen)
const m = $input.first().json;
const positionen = m.ama_meldepositionen.map(p => `
  <Position>
    <Rebsorte>${p.rebsorte_name}</Rebsorte>
    <FlaecheHa>${p.flaeche_ha}</FlaecheHa>
    <MengeKg>${p.menge_kg}</MengeKg>
    <Qualitaet>${p.qualitaetsstufe || 'qualitaetswein'}</Qualitaet>
  </Position>`).join('');

const xml = `<?xml version="1.0" encoding="UTF-8"?>
<AMAErntemeldung>
  <Betriebsnummer>${m.betriebsnummer}</Betriebsnummer>
  <Jahrgang>${new Date().getFullYear()}</Jahrgang>
  <Weinbaugebiet>${m.weinbaugebiet}</Weinbaugebiet>
  <Positionen>${positionen}
  </Positionen>
  <GesamtmengeKg>${m.gesamtmenge_kg}</GesamtmengeKg>
</AMAErntemeldung>`;

return [{ json: { ...m, xml_content: xml } }];
